CREATE TABLE memory_delivery_streams(workspace_id TEXT NOT NULL,member_id TEXT NOT NULL,device_id TEXT NOT NULL,sequence INTEGER NOT NULL,PRIMARY KEY(workspace_id,member_id,device_id)) STRICT;
CREATE TABLE memory_delivery_receipts(workspace_id TEXT NOT NULL,member_id TEXT NOT NULL,device_id TEXT NOT NULL,event_id TEXT NOT NULL,sequence INTEGER NOT NULL,digest TEXT NOT NULL,document TEXT NOT NULL,PRIMARY KEY(workspace_id,member_id,device_id,event_id),UNIQUE(workspace_id,member_id,device_id,sequence)) STRICT;
CREATE TABLE memory_delivery_sources(workspace_id TEXT NOT NULL,member_id TEXT NOT NULL,device_id TEXT NOT NULL,project_id TEXT NOT NULL,source_id TEXT NOT NULL,revision INTEGER NOT NULL,action TEXT NOT NULL,PRIMARY KEY(workspace_id,member_id,device_id,project_id,source_id)) STRICT;
